    ['code' => 'mle-deploy', 'prof' => 'ml-engineer', 'type' => 'technical', 'lvl' => [2, 4], 'diff' => 3, 'sec' => 210, 'skills' => ['software_engineering', 'cloud_devops'],
        'fr' => ['Décrivez comment vous passez d\'un modèle dans un notebook à un service en production.', 'Code, reproductibilité, packaging, déploiement, observabilité.',
